DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.guard_rental_order_refund()'::regprocedure) INTO definition; definition:=replace(definition,'EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.allocations) a WHERE coalesce(a->>''status'',''creating'')<>''succeeded'')','EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.allocations) done_item WHERE coalesce(done_item->>''status'',''creating'')<>''succeeded'')'); EXECUTE definition; END $$;